<?php
namespace App\Http\Controllers;
use App\Models\Event; use App\Models\Package; use App\Models\ParticipantChecklistItem; use App\Models\Registration; use Illuminate\Http\Request;
class EventRegistrationController extends Controller { public function create(Event $event) { return view('registrations.create', ['event'=>$event->load('packages.features')]); } public function store(Request $request, Event $event) { $data=$request->validate(['package_id'=>['required','exists:packages,id'],'single_room_requested'=>['nullable','boolean'],'roommate_preference'=>['nullable','string','max:255'],'checked_luggage_requested'=>['nullable','boolean']]); $package=Package::where('event_id',$event->id)->findOrFail($data['package_id']); $registration=Registration::create(['user_id'=>$request->user()->id,'event_id'=>$event->id,'package_id'=>$package->id,'status'=>'pending','payment_status'=>'deposit_invoiced','single_room_requested'=>$request->boolean('single_room_requested'),'roommate_preference'=>$data['roommate_preference']??null,'checked_luggage_requested'=>$request->boolean('checked_luggage_requested'),'total_amount_cents'=>$package->price_cents,'deposit_amount_cents'=>0]); foreach ($event->checklistItems as $item) ParticipantChecklistItem::firstOrCreate(['registration_id'=>$registration->id,'checklist_item_id'=>$item->id]); return redirect()->route('dashboard'); } }
